-- Store the supplied semester reference without inventing dated weekly occurrences.
CREATE TABLE IF NOT EXISTS semester_timetables (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  semester_key TEXT NOT NULL,
  data_json TEXT NOT NULL CHECK(json_valid(data_json)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE(user_id,semester_key)
);
CREATE INDEX IF NOT EXISTS timetable_owner ON semester_timetables(user_id,semester_key);

-- Import only for the existing owner who supplied the photo. No other account is seeded.
